window.PhysicaRankPyqNeet_botany_photosynthesisinhigherplants=[
{"id":"neet-2026-q097","pn":97,"y":"NEET 2026 · 3 May","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle ATP NADPH","q":"How many ATP and NADPH molecules are required to make one molecule of glucose through the Calvin pathway?","o":["18 ATP and 12 NADPH","6 ATP and 12 NADPH","24 ATP and 18 NADPH","12 ATP and 18 NADPH"],"c":0,"s":"Each turn of the Calvin pathway uses 3 ATP and 2 NADPH + H⁺ to fix one CO₂ molecule.\nOne glucose needs 6 turns.\nSo 6 × 3 = 18 ATP and 6 × 2 = 12 NADPH + H⁺ are needed."},
{"id":"neet-2026-q108","pn":108,"y":"NEET 2026 · 3 May","tp":"Photosynthesis in Higher Plants","st":"Photosynthesis statements","q":"Find the incorrect statement(s) about photosynthesis from the following:\nA. The water splitting complex is associated with PS I.\nB. C₄ plants use the C₃ pathway of CO₂ fixation as the main biosynthetic pathway.\nC. In C₄ plants, photorespiration does not occur.\nD. C₃ plants exhibit 'Kranz' anatomy.\nE. ATP synthesis in chloroplast occurs through chemiosmosis.","o":["B only","A and D only","B and C only","B and E only"],"c":1,"s":"A is incorrect: the water splitting complex is associated with PS II.\nB is correct: the C₃ pathway is the main biosynthetic pathway of CO₂ fixation in both C₃ and C₄ plants.\nC is a correct statement.\nD is incorrect: C₃ plants do not show Kranz anatomy.\nE is correct: ATP synthesis in chloroplast (photophosphorylation) occurs by chemiosmosis.\nSo the incorrect statements are A and D."},
{"id":"neet-2026r-q110","pn":110,"y":"Re-NEET 2026 · 21 Jun","tp":"Photosynthesis in Higher Plants","st":"Photorespiration","q":"Which of the following statements regarding photorespiration are correct?\n(a) Do not occur in C3 plants\n(b) CO₂ is consumed and O₂ is generated\n(c) Phosphoglycolate is formed\n(d) No synthesis of ATP and NADPH\nChoose the correct answer from the options given below:","o":["(c) and (d) only","(b) and (d) only","(a) and (b) only","(a) and (d) only"],"c":0,"s":"Photorespiration can occur in C3 plants, so (a) is wrong.\nIn photorespiration O₂ is consumed and CO₂ is released, so (b) is wrong.\nPhosphoglycolate is formed as the first product, so (c) is correct.\nThere is no synthesis of ATP and NADPH in photorespiration, so (d) is correct."},
{"id":"neet-2026r-q117","pn":117,"y":"Re-NEET 2026 · 21 Jun","tp":"Photosynthesis in Higher Plants","st":"Photorespiration","q":"Photorespiration reaction catalyzed by RuBisCo is shown below:\nRuBP + O₂ → 3-Phosphoglycerate + X.\nIdentify \"X\" from the given options:","o":["2-Phosphoglycolate","Oxaloacetate","Malate","Phosphoenolpyruvate"],"c":0,"s":"In photorespiration RuBP binds with O₂.\nInstead of giving 2 molecules of PGA, it gives one molecule each of phosphoglycerate and phosphoglycolate.\nSo X is 2-phosphoglycolate."},
{"id":"neet-2026r-q120","pn":120,"y":"Re-NEET 2026 · 21 Jun","tp":"Photosynthesis in Higher Plants","st":"Reaction centres","q":"Which pigment has absorption peak at 700 nm in the photosynthetic reaction centre PS I (P700)?","o":["Chlorophyll a","Xanthophylls","Carotenoids","Chlorophyll b"],"c":0,"s":"In PS I the reaction centre chlorophyll a has an absorption peak at 700 nm.\nHence it is called P₇₀₀."},
{"id":"neet-2026r-q126","pn":126,"y":"Re-NEET 2026 · 21 Jun","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle","q":"How many turns of Calvin cycle are required for the formation of three molecules of glucose?","o":["3","1","18","6"],"c":2,"s":"One molecule of glucose needs 6 turns of the cycle.\nFor three molecules: 6 × 3 = 18 turns."},
{"id":"neet-2026r-q129","pn":129,"y":"Re-NEET 2026 · 21 Jun","tp":"Photosynthesis in Higher Plants","st":"Early experiments","q":"Select the correct sequence of experiments that led to a gradual understanding of photosynthesis in green plants.","o":["Role of air → release of oxygen → production of glucose → absorption spectra of chlorophyll a and b","Release of oxygen → production of glucose → absorption spectra of chlorophyll a and b → role of air","Production of glucose → role of air → release of oxygen → absorption spectra of chlorophyll a and b","Absorption spectra of chlorophyll a and b → production of glucose → release of oxygen → role of air"],"c":0,"s":"The correct sequence of experiments is:\nRole of air in making glucose (Joseph Priestley's bell jar experiment, 1770).\nRelease of oxygen (Jan Ingenhousz's experiment with an aquatic plant).\nProduction of glucose (Julius von Sachs, 1854).\nAbsorption spectra of chlorophyll a and b (T.W. Engelmann's experiment)."},
{"id":"neet-2026-q132","pn":132,"y":"NEET 2026 · 3 May","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle","q":"The enzyme required for carboxylation in the Calvin cycle is","o":["PEP carboxylase","RuBP carboxylase - oxygenase","Carboxypeptidase","Hexokinase"],"c":1,"s":"RuBisCO (RuBP carboxylase-oxygenase) is the enzyme required for carboxylation in the Calvin cycle."},
{"id":"neet-2025-q122","pn":122,"y":"NEET 2025","tp":"Photosynthesis in Higher Plants","st":"Leaf pigments","q":"Match List I with List II:\nList-I: A. Chlorophyll a; B. Chlorophyll b; C. Xanthophylls; D. Carotenoids\nList-II: (I) Yellow-green; (II) Yellow; (III) Blue-green; (IV) Yellow to Yellow-orange\nChoose the option with all correct matches.","o":["A-III, B-IV, C-II, D-I","A-III, B-I, C-II, D-IV","A-I, B-II, C-IV, D-III","A-I, B-IV, C-III, D-II"],"c":1,"s":"A chromatographic separation of leaf pigments shows that the colour we see in leaves is due to four pigments, not a single pigment.\nChlorophyll a: bright or blue-green in the chromatogram.\nChlorophyll b: yellow-green.\nXanthophylls: yellow.\nCarotenoids: yellow to yellow-orange.","sfig":{"w":330,"h":100,"alt":"Table of leaf pigments and their colour in the chromatogram.","d":[["r",2,2,326,96],["l",90,2,90,98],["l",116,2,116,98],["t",8,19,"Chlorophyll a","s"],["t",103,19,"–","m"],["t",124,19,"Bright or blue-green in the chromatogram","s"],["l",2,26,328,26],["t",8,43,"Chlorophyll b","s"],["t",103,43,"–","m"],["t",124,43,"Yellow-green","s"],["l",2,50,328,50],["t",8,67,"Xanthophylls","s"],["t",103,67,"–","m"],["t",124,67,"Yellow","s"],["l",2,74,328,74],["t",8,91,"Carotenoids","s"],["t",103,91,"–","m"],["t",124,91,"Yellow to Yellow-orange","s"]]}},
{"id":"neet-2025-q171","pn":171,"y":"NEET 2025","tp":"Photosynthesis in Higher Plants","st":"RuBisCO","q":"Which of the following statements about RuBisCO is true?","o":["It is active only in the dark","It has higher affinity for oxygen than carbon dioxide","It is an enzyme involved in the photolysis of water","It catalyzes the carboxylation of RuBP"],"c":3,"s":"Carboxylation is the most crucial step of the Calvin cycle, where CO₂ is used to carboxylate RuBP.\nThis reaction is catalysed by the enzyme RuBP carboxylase.\nThis enzyme also has oxygenase activity, but RuBisCO has higher affinity for carbon dioxide than oxygen."},
{"id":"neet-2024-q106","pn":106,"y":"NEET 2024 · 5 May","tp":"Photosynthesis in Higher Plants","st":"Dark reaction requirements","q":"Which of the following are required for the dark reaction of photosynthesis?\n(A) Light  (B) Chlorophyll  (C) CO₂  (D) ATP  (E) NADPH\nChoose the correct answer from the options given below :","o":["C, D and E only","D and E only","A, B and C only","B, C and D only"],"c":0,"s":"The dark reaction needs CO₂, ATP and NADPH.\nLight and chlorophyll are needed only for the light reaction.\nSo the answer is C, D and E only."},
{"id":"neet-2024-q111","pn":111,"y":"NEET 2024 · 5 May","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle","q":"How many molecules of ATP and NADPH are required for every molecule of CO₂ fixed in the calvin cycle?","o":["3 molecules of ATP and 3 molecules of NADPH","3 molecules of ATP and 2 molecules of NADPH","2 molecules of ATP and 3 molecules of NADPH","2 molecules of ATP and 2 molecules of NADPH"],"c":1,"s":"For fixing one molecule of CO₂ in the Calvin cycle, 3 ATP molecules and 2 NADPH molecules are needed."},
{"id":"neet-2024-q142","pn":142,"y":"NEET 2024 · 5 May","tp":"Photosynthesis in Higher Plants","st":"Photorespiration","q":"Given below are two statements:\nStatement I : In C₃ Plants, some O₂ binds RuBisCO, hence CO₂ fixation is decreased.\nStatement II: In C₄ plants, mesophyll cells show very little photorespiration while bundle sheath cells do not show photorespiration.\nIn the light of the above statements, choose the correct answer from the options given below:","o":["Statement I is true but Statement II is false","Statement I is false but Statement II is true","Both Statement I and Statement II are true","Both Statement I and Statement II are false"],"c":0,"s":"In C₃ plants some O₂ binds to RuBisCO, so CO₂ fixation falls. Statement I is true.\nStatement II is wrong: in C₄ plants photorespiration does not occur because RuBisCO is absent in the mesophyll (it is in the bundle sheath).\nSo only Statement I is correct."},
{"id":"neet-2023-q115","pn":115,"y":"NEET 2023 · 7 May","tp":"Photosynthesis in Higher Plants","st":"Photosystems I and II","q":"The reaction centre in PS II has an absorption maxima at -","o":["780 nm","680 nm","700 nm","660 nm"],"c":1,"s":"In PS I the reaction centre chlorophyll a peaks at 700 nm.\nIn PS II the reaction centre absorbs maximum at 680 nm."},
{"id":"neet-2023-q130","pn":130,"y":"NEET 2023 · 7 May","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle ATP NADPH","q":"How many ATP and NADPH2 are required for the synthesis of one molecule of Glucose during Calvin cycle?","o":["18 ATP and 16 NADPH2","12 ATP and 12 NADPH2","18 ATP and 12 NADPH2","12 ATP and 16 NADPH2"],"c":2,"s":"Each CO₂ entering the Calvin cycle needs 3 ATP and 2 NADPH₂.\nOne glucose needs 6 turns of the cycle.\nSo ATP = 6 × 3 = 18 and NADPH₂ = 6 × 2 = 12."},
{"id":"neet-2023-q140","pn":140,"y":"NEET 2023 · 7 May","tp":"Photosynthesis in Higher Plants","st":"Chemiosmosis requirements","q":"Which of the following combinations is required for chemiosmosis?","o":["Proton pump, electron gradient, NADP synthase","Membrane, proton pump, proton gradient, ATP synthase","Membrane, proton pump, proton gradient, NADP synthase","Proton pump, electron gradient, ATP synthase"],"c":1,"s":"Chemiosmosis needs a membrane, a proton pump, a proton gradient and ATP synthase."},
{"id":"neet-2022-q102","pn":102,"y":"NEET 2022 · 17 Jul","tp":"Photosynthesis in Higher Plants","st":"C4 pathway","q":"Given below are two statements :\nStatement I : The primary CO₂ acceptor in C₄ plants is phosphoenolpyruvate and is found in the mesophyll cells.\nStatement II : Mesophyll cells of C₄ plants lack RuBisCo enzyme. In the light of the above statements, choose the correct answer from the options given below:","o":["Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are correct"],"c":3,"s":"The primary CO₂ acceptor in C₄ plants is PEP, a 3-carbon molecule, in mesophyll cells.\nC₄ mesophyll cells have no RuBisCO.\nSo both statements are correct."},
{"id":"neet-2022r-q110","pn":110,"y":"Re-NEET 2022 · 4 Sep","tp":"Photosynthesis in Higher Plants","st":"Calvin cycle reduction phase","q":"When one CO₂ molecule is fixed as one molecule of triose phosphate, which of the following photochemically made, high energy chemical intermediates are used in the reduction phase?","o":["2 ATP + 2 NADPH","1 ATP + 1 NADPH","1 ATP + 2 NADPH","2 ATP + 1 NADPH"],"c":3,"s":"Fixing one CO₂ into one triose phosphate uses 2 ATP and 1 NADPH."},
{"id":"neet-2022-q133","pn":133,"y":"NEET 2022 · 17 Jul","tp":"Photosynthesis in Higher Plants","st":"Chemiosmosis ATP synthesis","q":"Which one of the following is not true regarding the release of energy during ATP synthesis through chemiosmosis? It involves:","o":["Breakdown of electron gradient","Movement of protons across the membrane to the stroma","Reduction of NADP to NADPH2 on the stroma side of the membrane","Breakdown of proton gradient"],"c":0,"s":"Chemiosmosis needs a membrane, a proton pump, a proton gradient and ATP synthase.\nEnergy is used to pump protons into the thylakoid lumen, making a high proton concentration there.\nNADP reductase sits on the stroma side.\nIt uses electrons from the PS I acceptor and protons to reduce NADP⁺ to NADPH + H⁺.\nThe process involves breaking the proton gradient, not an electron gradient."},
{"id":"neet-2022-q138","pn":138,"y":"NEET 2022 · 17 Jul","tp":"Photosynthesis in Higher Plants","st":"C4 pathway Kranz anatomy","q":"What is the role of large bundle sheath cells found around the vascular bundles in C4 plants?","o":["To increase the number of chloroplast for the operation of Calvin cycle","To enable the plant to tolerate high temperature","To protect the vascular tissue from high light intensity","To provide the site for photorespiratory pathway"],"c":0,"s":"In C4 plants the large cells around vascular bundles form the bundle sheath.\nThese cells hold many chloroplasts.\nThe Calvin cycle runs in them."},
{"id":"neet-2022r-q148","pn":148,"y":"Re-NEET 2022 · 4 Sep","tp":"Photosynthesis in Higher Plants","st":"Chemiosmotic hypothesis","q":"Identify the correct statements regarding chemiosmotic hypothesis\n(a) Splitting of the water molecule takes place on the inner side of the membrane.\n(b) Protons accumulate within the lumen of the thylakoids.\n(c) Primary acceptor of electron transfers the electrons to an electron carrier.\n(d) NADP reductase enzyme is located on the stroma side of the membrane.\n(e) Protons increase in number in stroma.\nChoose the correct answer from the options given below :","o":["(b), (c) and (e)","(a), (b) and (e)","(a), (b) and (d)","(b), (c) and (d)"],"c":2,"s":"(c) is wrong: the primary acceptor passes electrons to a proton carrier (plastoquinone), not an electron carrier.\n(e) is wrong: protons build up in the thylakoid lumen and fall on the stroma side.\nStatements (a), (b) and (d) are correct."},
{"id":"neet-2021-q103","pn":103,"y":"NEET 2021 · 12 Sep","tp":"Photosynthesis in Higher Plants","st":"C4 pathway","q":"The first stable product of CO₂ fixation in Sorghum is","o":["Phosphoglyceric acid","Pyruvic acid","Oxaloacetic acid","Succinic acid"],"c":2,"s":"Sorghum is a C4 plant.\nIn C4 plants, CO₂ is first fixed by PEP carboxylase in mesophyll cells, giving the 4-carbon oxaloacetic acid.\nPGA is the first product in C3 plants; pyruvic acid ends glycolysis; succinic acid is a Krebs cycle intermediate."},
{"id":"neet-2021-q141","pn":141,"y":"NEET 2021 · 12 Sep","tp":"Photosynthesis in Higher Plants","st":"Light reaction","q":"Which of the following statements is incorrect ?","o":["Cyclic photophosphorylation involves both PS I and PS II","Both ATP and NADPH + H⁺ are synthesized during non-cyclic photophosphorylation","Stroma lamellae have PS I only and lack NADP reductase","Grana lamellae have both PS I and PS II"],"c":0,"s":"Cyclic photophosphorylation uses only PS I, so statement 1 is wrong.\nNon-cyclic flow uses both photosystems and makes ATP and NADPH.\nGrana lamellae have PS I and PS II; stroma lamellae have only PS I and lack NADP reductase."},
{"id":"neet-2020-q006","pn":6,"y":"NEET 2020 · 13 Sep","tp":"Photosynthesis in Higher Plants","st":"Photorespiration","q":"The oxygenation activity of RuBisCo enzyme in photorespiration leads to the formation of :","o":["1 molecule of 3-C compound","1 molecule of 6-C compound","1 molecule of 4-C compound and 1 molecule of 2-C compound","2 molecules of 3-C compound"],"c":0,"s":"In oxygenation RuBisCO adds O₂ to RuBP.\nThis gives one 3-C compound (PGA) and one 2-C compound (phosphoglycolate).\nThe printed key (1) is kept.\nNote: Printed answer 1; oxygenation actually gives one 3-C and one 2-C molecule, and none of the options states this fully."},
{"id":"neet-2020-q007","pn":7,"y":"NEET 2020 · 13 Sep","tp":"Photosynthesis in Higher Plants","st":"Electron transport chain","q":"In light reaction, plastoquinone facilitates the transfer of electrons from :","o":["Cytb6f complex to PS-I","PS-I to NADP+","PS-I to ATP synthase","PS-II to Cytb6f complex"],"c":3,"s":"Electrons leave PS-II and are accepted by plastoquinone.\nPlastoquinone passes them to the Cytb₆f complex.\nSo it carries electrons from PS-II to Cytb₆f."},
{"id":"neet-2018-q101","pn":101,"y":"NEET 2018 · 6 May","tp":"Photosynthesis in Higher Plants","st":"Products of light reaction","q":"Which of the following is not a product of light reaction of photosynthesis ?","o":["ATP","NADH","NADPH","Oxygen"],"c":1,"s":"The light reaction makes ATP (photophosphorylation), NADPH (reduction of NADP⁺) and O₂ (photolysis of water).\nNADH is made in respiration, not in photosynthesis."},
{"id":"neet-2018-q130","pn":130,"y":"NEET 2018 · 6 May","tp":"Photosynthesis in Higher Plants","st":"Oxygenic and anoxygenic photosynthesis","q":"Oxygen is not produced during photosynthesis by -","o":["Green sulphur bacteria","Nostoc","Cycas","Chara"],"c":0,"s":"Cyanobacteria (Nostoc), algae (Chara) and plants (Cycas) split water and release O₂.\nGreen sulphur bacteria use H₂S instead of water, so they do not release O₂."}
];
